mapper.update:
UPDATE eq_equipment SET equipment_name = #{equipmentName}, equipment_type = #{equipmentType},
    model = #{model}, location = #{location}, remark = #{remark}, version = version + 1,
    update_by = #{updateBy}, update_time = #{updateTime}
WHERE equipment_id = #{equipmentId} AND version = #{version}

UPDATE eq_equipment SET equipment_status = #{equipmentStatus}, version = version + 1,
    update_by = #{updateBy}, update_time = #{updateTime}
WHERE equipment_id = #{equipmentId} AND version = #{version}

mapper.select:
SELECT w.work_order_id, w.work_order_no, w.title, w.symptom, w.fault_category, w.priority,
    w.status, w.occurred_time, w.create_time, r.nick_name AS reporter_name, h.nick_name AS handler_name
FROM eq_work_order w
LEFT JOIN sys_user r ON r.user_id = w.reporter_id
LEFT JOIN sys_user h ON h.user_id = w.handler_id
WHERE w.equipment_id = #{id}

    AND (1 = 0
        OR w.reporter_id = #{userId}
        OR w.handler_id = #{userId}
    )

ORDER BY w.create_time DESC, w.work_order_id DESC
